package com.know.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="activity") public class Activity { @Id private UUID id=UUID.randomUUID();@Column(name="user_id",nullable=false)private UUID userId;@Column(name="path_id")private UUID pathId;@Column(name="item_id")private UUID itemId;@Enumerated(EnumType.STRING)@Column(nullable=false)private ActivityType type;@Column(nullable=false,length=240)private String title;@Column(columnDefinition="text")private String detail;@Column(name="occurred_at",nullable=false)private Instant occurredAt=Instant.now();protected Activity(){}public Activity(UUID userId,UUID pathId,UUID itemId,ActivityType type,String title,String detail){this(userId,pathId,itemId,type,title,detail,Instant.now());}public Activity(UUID userId,UUID pathId,UUID itemId,ActivityType type,String title,String detail,Instant occurredAt){this.userId=userId;this.pathId=pathId;this.itemId=itemId;this.type=type;this.title=title;this.detail=detail;this.occurredAt=occurredAt;}public UUID getId(){return id;}public UUID getPathId(){return pathId;}public UUID getItemId(){return itemId;}public ActivityType getType(){return type;}public String getTitle(){return title;}public String getDetail(){return detail;}public Instant getOccurredAt(){return occurredAt;}}
